/* Ensure hidden attribute is never overridden by display declarations */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1a102f;
  --color-panel: #2b1f4d;
  --color-accent: #fcd34d;
  --color-text: #f8fafc;
  --color-btn: #3b82f6;
  --color-btn-hover: #2563eb;
  --color-btn-active: #1d4ed8;
  --color-border: #0f0a1c;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: 'Courier New', Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  line-height: 1.5;
  background-image: 
    linear-gradient(45deg, #150d27 25%, transparent 25%), 
    linear-gradient(-45deg, #150d27 25%, transparent 25%), 
    linear-gradient(45deg, transparent 75%, #150d27 75%), 
    linear-gradient(-45deg, transparent 75%, #150d27 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0;
}

.quiz-container {
  width: 100%;
  max-width: 580px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.quiz-header {
  background-color: var(--color-panel);
  border: 4px solid var(--color-border);
  box-shadow: 6px 6px 0px var(--color-border);
  padding: 16px;
  text-align: center;
}

.title {
  font-size: 1.75rem;
  letter-spacing: 2px;
  color: var(--color-accent);
  text-shadow: 2px 2px 0px var(--color-border);
  margin-bottom: 12px;
}

.status-bar {
  display: flex;
  justify-content: space-around;
  background: var(--color-bg);
  border: 3px solid var(--color-border);
  padding: 8px 16px;
  font-size: 1.1rem;
  font-weight: bold;
}

.status-item {
  display: flex;
  gap: 8px;
  align-items: center;
}

.label {
  color: var(--color-accent);
}

.value {
  color: #fff;
}

.card-panel {
  background-color: var(--color-panel);
  border: 4px solid var(--color-border);
  box-shadow: 6px 6px 0px var(--color-border);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.question-meta {
  display: flex;
  justify-content: flex-start;
}

.badge {
  background-color: var(--color-bg);
  border: 2px solid var(--color-border);
  color: var(--color-accent);
  padding: 4px 10px;
  font-size: 0.85rem;
  font-weight: bold;
}

.question-text {
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.4;
  min-height: 56px;
}

.options-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

@media (min-width: 500px) {
  .options-grid {
    grid-template-columns: 1fr 1fr;
  }
}

.pixel-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  color: #ffffff;
  background-color: var(--color-btn);
  border: 3px solid var(--color-border);
  box-shadow: 4px 4px 0px var(--color-border);
  padding: 14px 16px;
  cursor: pointer;
  text-align: left;
  display: flex;
  align-items: center;
  gap: 10px;
  outline: none;
  transition: none;
  user-select: none;
}

.pixel-btn:hover {
  background-color: var(--color-btn-hover);
  transform: translate(-1px, -1px);
  box-shadow: 5px 5px 0px var(--color-border);
}

.pixel-btn:focus-visible {
  outline: 3px dashed var(--color-accent);
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(3px, 3px);
  box-shadow: 1px 1px 0px var(--color-border);
  background-color: var(--color-btn-active);
}

.option-prefix {
  background-color: rgba(0, 0, 0, 0.25);
  padding: 2px 6px;
  border: 1px solid var(--color-border);
  font-size: 0.9rem;
}

.text-center {
  text-align: center;
  align-items: center;
}

.game-over-title {
  font-size: 2rem;
  color: var(--color-accent);
  letter-spacing: 2px;
}

.finish-reason {
  font-size: 1.1rem;
  color: var(--color-text);
}

.final-score-box {
  background: var(--color-bg);
  border: 3px solid var(--color-border);
  padding: 16px 32px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 12px 0;
}

.final-label {
  font-size: 0.9rem;
  color: var(--color-accent);
}

.final-score-value {
  font-size: 2.2rem;
  font-weight: bold;
}

.action-btn {
  text-align: center;
  justify-content: center;
  width: 100%;
  max-width: 240px;
  background-color: #10b981;
}

.action-btn:hover {
  background-color: #059669;
}

.action-btn:active {
  background-color: #047857;
}

document.addEventListener('DOMContentLoaded', () => {
  const questions = [
    {
      question: 'Which HTML element holds JavaScript code?',
      options: ['<script>', '<javascript>', '<js>', '<code>'],
      answer: 0
    },
    {
      question: 'What is the correct syntax for a CSS class selector?',
      options: ['#class', '.class', '*class', '$class'],
      answer: 1
    },
    {
      question: 'Which method adds an event listener to an element?',
      options: ['attachEvent()', 'listen()', 'addEventListener()', 'onEvent()'],
      answer: 2
    },
    {
      question: 'What value is returned by typeof null in JavaScript?',
      options: ['"undefined"', '"null"', '"object"', '"boolean"'],
      answer: 2
    },
    {
      question: 'Which keyword creates a block-scoped variable in modern JS?',
      options: ['var', 'let', 'global', 'set'],
      answer: 1
    }
  ];

  const TOTAL_TIME = 60;
  let timeLeft = TOTAL_TIME;
  let timerInterval = null;
  let currentQuestionIndex = 0;
  let score = 0;

  const timerDisplay = document.getElementById('timer-display');
  const scoreDisplay = document.getElementById('score-display');
  const quizScreen = document.getElementById('quiz-screen');
  const gameOverScreen = document.getElementById('game-over-screen');
  const questionCounter = document.getElementById('question-counter');
  const questionText = document.getElementById('question-text');
  const optionsGrid = document.getElementById('options-grid');
  const finalScoreDisplay = document.getElementById('final-score-display');
  const finishReason = document.getElementById('finish-reason');
  const restartBtn = document.getElementById('restart-btn');

  function startTimer() {
    clearInterval(timerInterval);
    timeLeft = TOTAL_TIME;
    timerDisplay.textContent = `${timeLeft}s`;

    timerInterval = setInterval(() => {
      timeLeft -= 1;
      if (timeLeft <= 0) {
        timeLeft = 0;
        timerDisplay.textContent = '0s';
        clearInterval(timerInterval);
        endQuiz('Time Expired!');
      } else {
        timerDisplay.textContent = `${timeLeft}s`;
      }
    }, 1000);
  }

  function showQuestion(index) {
    const currentQ = questions[index];
    questionCounter.textContent = `QUESTION ${index + 1} OF ${questions.length}`;
    questionText.textContent = currentQ.question;
    optionsGrid.innerHTML = '';

    const prefixes = ['A', 'B', 'C', 'D'];
    currentQ.options.forEach((optText, i) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'pixel-btn';
      btn.setAttribute('data-index', i.toString());

      const prefixSpan = document.createElement('span');
      prefixSpan.className = 'option-prefix';
      prefixSpan.textContent = prefixes[i];

      const textNode = document.createTextNode(optText);
      btn.appendChild(prefixSpan);
      btn.appendChild(textNode);

      btn.addEventListener('click', () => handleAnswer(i));
      optionsGrid.appendChild(btn);
    });
  }

  function handleAnswer(selectedIndex) {
    if (selectedIndex === questions[currentQuestionIndex].answer) {
      score += 1;
      scoreDisplay.textContent = score.toString();
    }

    currentQuestionIndex += 1;
    if (currentQuestionIndex < questions.length) {
      showQuestion(currentQuestionIndex);
    } else {
      endQuiz('All Questions Answered!');
    }
  }

  function endQuiz(reason) {
    clearInterval(timerInterval);
    quizScreen.hidden = true;
    gameOverScreen.hidden = false;
    finishReason.textContent = reason;
    finalScoreDisplay.textContent = `${score} / ${questions.length}`;
    restartBtn.focus();
  }

  function restartQuiz() {
    score = 0;
    currentQuestionIndex = 0;
    scoreDisplay.textContent = '0';
    gameOverScreen.hidden = true;
    quizScreen.hidden = false;
    showQuestion(currentQuestionIndex);
    startTimer();
  }

  restartBtn.addEventListener('click', restartQuiz);

  // Initial boot
  restartQuiz();
});
